import{_ as i,o as l,c as t,ag as o}from"./chunks/framework.DNmTgtHf.js";const d=JSON.parse('{"title":"Resources by Format","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/reference/Resources.md","filePath":"todo/study_plan/reference/Resources.md"}'),a={name:"todo/study_plan/reference/Resources.md"};function n(s,e,r,c,u,m){return l(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="resources-by-format" tabindex="-1">Resources by Format <a class="header-anchor" href="#resources-by-format" aria-label="Permalink to &quot;Resources by Format&quot;">​</a></h1><p>Reference list of books, videos/courses, blogs/newsletters, and tools that show up across the study-plan track. Not part of the study plan itself — kept separate so the per-Part docs stay focused on topics, not references.</p><p>Use this as a lookup. Don&#39;t try to read everything. Pick one book per Part-cluster when you reach that phase of the study plan — DDIA when you hit Databases + HLD, JCIP when you hit Concurrency, Bulletproof TLS when you hit Security stack, etc.</p><hr><h2 id="books-—-the-canonical-ones" tabindex="-1">Books — the canonical ones <a class="header-anchor" href="#books-—-the-canonical-ones" aria-label="Permalink to &quot;Books — the canonical ones&quot;">​</a></h2><ul><li><em>Designing Data-Intensive Applications</em> — Martin Kleppmann (the single most important book)</li><li><em>Database Internals</em> — Alex Petrov</li><li><em>Java Concurrency in Practice</em> — Brian Goetz</li><li><em>Effective Java</em> — Joshua Bloch</li><li><em>Spring in Action</em> — current edition</li><li><em>Release It!</em> — Michael Nygard (resilience patterns)</li><li><em>System Design Interview Vol 1 &amp; 2</em> — Alex Xu</li><li><em>Bulletproof TLS and PKI</em> — Ivan Ristić</li><li><em>Serious Cryptography</em> — Jean-Philippe Aumasson</li><li><em>Designing Distributed Systems</em> — Brendan Burns</li><li><em>Refactoring</em> — Martin Fowler</li><li><em>Head First Design Patterns</em></li><li><em>Domain-Driven Design Distilled</em> — Vaughn Vernon (gentle DDD intro)</li><li><em>Site Reliability Engineering</em> — Google (free online)</li><li><em>Hands-On Large Language Models</em> — Jay Alammar</li></ul><h2 id="videos-courses" tabindex="-1">Videos / courses <a class="header-anchor" href="#videos-courses" aria-label="Permalink to &quot;Videos / courses&quot;">​</a></h2><ul><li>Andrej Karpathy — Zero to Hero, Intro to LLMs (free)</li><li>Hussein Nasser — networking deep dives (YouTube, exceptional)</li><li>ByteByteGo — Alex Xu</li><li>Gaurav Sen — system design (Hindi/English options)</li><li>HelloInterview.com — mock system design walkthroughs</li><li>AWS re:Invent recorded talks — search by topic</li><li>Jepsen analyses — Kyle Kingsbury (consistency in real DBs)</li></ul><h2 id="blogs-newsletters" tabindex="-1">Blogs / newsletters <a class="header-anchor" href="#blogs-newsletters" aria-label="Permalink to &quot;Blogs / newsletters&quot;">​</a></h2><ul><li>High Scalability</li><li>AWS Architecture Center</li><li>Netflix Tech Blog</li><li>Stripe Engineering</li><li>Cloudflare Blog</li><li>Discord Engineering</li><li>Uber Engineering</li><li>The Pragmatic Engineer (newsletter)</li><li>Martin Kleppmann&#39;s blog &amp; talks</li></ul><h2 id="tools-to-be-fluent-in" tabindex="-1">Tools to be fluent in <a class="header-anchor" href="#tools-to-be-fluent-in" aria-label="Permalink to &quot;Tools to be fluent in&quot;">​</a></h2><ul><li>IntelliJ IDEA (or your IDE), with profilers</li><li>jq, yq, curl, httpie</li><li>openssl daily commands</li><li>kubectl</li><li>terraform</li><li>Postman / Insomnia / Bruno</li><li>PlantUML / Mermaid</li></ul>',12)])])}const p=i(a,[["render",n]]);export{d as __pageData,p as default};
